#include <stdio.h>

enum Mode {
    RUN_NORMALLY = '0',
    SIMULATE_OPEN_FAILURE = '1',
    SIMULATE_WRITE_FAILURE = '2'
};

static int read_mode(void)
{
    int mode = getchar();
    if (mode == EOF) {
        return ferror(stdin) ? -1 : RUN_NORMALLY;
    }
    int tail = getchar();
    if (tail == '\n') {
        tail = getchar();
    }
    if (tail != EOF || ferror(stdin)) {
        return -1;
    }
    return mode == RUN_NORMALLY || mode == SIMULATE_OPEN_FAILURE ||
           mode == SIMULATE_WRITE_FAILURE ? mode : -1;
}

int main(void)
{
    int mode = read_mode();
    if (mode == -1) {
        puts("invalid-mode");
        return 1;
    }

    FILE *input = fopen("input/reading.txt", "rb");
    FILE *output = NULL;
    const char *problem = NULL;
    if (input == NULL) {
        problem = "open-input-error";
    } else {
        if (mode != SIMULATE_OPEN_FAILURE) {
            output = fopen("received.txt", "wb");
        }
        if (output == NULL) {
            problem = "open-output-error";
        } else {
            int byte;
            while ((byte = fgetc(input)) != EOF) {
                if (mode == SIMULATE_WRITE_FAILURE) {
                    problem = "write-error";
                    break;
                }
                if (fputc(byte, output) == EOF) {
                    problem = "write-error";
                    break;
                }
            }
            if (problem == NULL && ferror(input)) {
                problem = "read-error";
            }
        }
    }

    int closed_input = 0;
    int closed_output = 0;
    if (input != NULL) {
        ++closed_input;
        if (fclose(input) == EOF && problem == NULL) {
            problem = "close-input-error";
        }
    }
    if (output != NULL) {
        ++closed_output;
        if (fclose(output) == EOF && problem == NULL) {
            problem = "close-output-error";
        }
    }

    puts(problem == NULL ? "ok" : problem);
    printf("closed-input %d\nclosed-output %d\n", closed_input, closed_output);
    return problem == NULL ? 0 : 1;
}

